INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (1, 'EASY', 'Wlazł kotek na płotek i mruga, ładna to piosenka, nie długa. Nie długa, nie krótka, lecz w sam raz, zaśpiewaj koteczku, jeszcze raz.', 'Wlazł kotek na płotek');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (2, 'EASY', 'My jesteśmy krasnoludki. Hopsa sa hopsa sa. Pod grzybkami nasze budki. Hopsa hopsa sa. Jemy mrówki żabkie łapki. Oj tak tak oj tak tak. A na głowach krasne czapki. To nasz to nasz znak. Gdy ktoś zbłądzi to trąbimy. Trututu trututu. Gdy ktoś senny to uśpimy. Lulu lulu lu. Gdy ktoś skrzywdzi krasnoludka. Ajajaj ajajaj. To zapłacze niezabudka. Uh uh.', 'My jesteśmy krasnoludki');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (3, 'EASY', 'Stary niedźwiedź mocno śpi. Stary niedźwiedź mocno śpi. My go nie zbudzimy bo się go boimy. Jak się zbudzi to nas zje. Jak się zbudzi to nas zje. Pierwsza godzina niedźwiedź śpi. Druga godzina niedźwiedź śpi. Trzecia godzina niedźwiedź chrapie. Czwarta godzina niedźwiedź łapie. Stary niedźwiedź mocno śpi. Stary niedźwiedź mocno śpi. My go nie zbudzimy bo się go boimy. Jak się zbudzi to nas zje. Jak się zbudzi to nas zje. Pierwsza godzina niedźwiedź śpi. Druga godzina niedźwiedź śpi. Trzecia godzina niedźwiedź chrapie. Czwarta godzina niedźwiedź łapie.', 'Stary niedźwiedź mocno śpi');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (4, 'EASY', 'Lata osa koło nosa. Lata mucha koło ucha. Lata bąk koło rąk. Lecą ważki koło paszki. Lata pszczoła koło czoła. Lata mucha koło brzucha. Lecą muszki koło nóżki. Biegną mrówki koło główki.', 'Lata osa');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (5, 'EASY', 'Gdy się witamy mówimy „cześć", Sześć razy sześć – trzydzieści sześć. W moim albumie kolekcja zdjęć, Pięć razy pięć – dwadzieścia pięć. Stado kangurów unika lwa, Sześć razy siedem – czterdzieści dwa. W sklepie sprzedają nowe rowery. Sześć razy dziewięć – pięćdziesiąt cztery.', 'Sześć razy sześć');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (6, 'EASY', 'Murzynek Bambo w Afryce mieszka, czarną ma skórę ten nasz koleżka. Uczy się pilnie przez całe ranki Ze swej murzyńskiej pierwszej czytanki. A gdy do domu ze szkoły wraca, Psoci, figluje - to jego praca. Aż mama krzyczy:  "Bambo, łobuzie!" A Bambo czarną nadyma buzię. Mama powiada: "Napij się mleka" A on na drzewo mamie ucieka. Mama powiada: "Chodź do kąpieli", A on się boi że się wybieli. Lecz mama kocha swojego synka. Bo dobry chłopak z tego murzynka. Szkoda że Bambo czarny, wesoły nie chodzi razem z nami do szkoły.', 'Murzynek Bambo');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (7, 'MEDIUM', 'W Szczebrzeszynie chrząszcz brzmi w trzcinie I Szczebrzeszyn z tego słynie. Wół go pyta: „Panie chrząszczu, Po co pan tak brzęczy w gąszczu?" „Jak to - po co? To jest praca, Każda praca się opłaca". „A cóż za to pan dostaje?" „Też pytanie! Wszystkie gaje, Wszystkie trzciny po wsze czasy, Łąki, pola oraz lasy, Nawet rzeczki, nawet zdroje, Wszystko to jest właśnie moje!" Wół pomyślał: „Znakomicie, Też rozpocznę takie życie". Wrócił do dom i wesoło Zaczął brzęczeć pod stodołą Po wolemu, tęgim basem. A tu Maciek szedł tymczasem. Jak nie wrzaśnie: „Cóż to znaczy? Czemu to się wół próżniaczy?!" „Jak to? Czyż ja nic nie robię? Przecież właśnie brzęczę sobie!" „Ja ci tu pobrzęczę, wole, Dosyć tego! Jazda w pole!" I dał taką mu robotę, Że się wół oblewał potem. Po robocie pobiegł w gąszcze. „Już ja to na chrząszczu pomszczę!" Lecz nie zastał chrząszcza w trzcinie, Bo chrząszcz właśnie brzęczał w Pszczynie.', 'W Szczebrzeszynie');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (8, 'MEDIUM', 'Siedzi Ciaptak na dachu I wszystkim napędza strachu. Ludzie patrzą, brednie plotą, Bo żaden z nich nie wie, co to. „Widzieliście Ciaptaka? Czy to jest odmiana ptaka? Czy może roślina taka? Czy może garnek, czy bania? Czy może głowa barania? A może to rodzaj grzyba? A może po prostu ryba? A może zwyczajny płaz?" Ktoś go gdzieś widział już raz, Ale też nie na pewno, Bo wtedy wyglądał jak drewno Pomalowane z dwóch stron, Więc chyba to nie był on. Sprowadzono z drabiną strażaka, Żeby ściągnął z dachu Ciaptaka. Rzekł strażak: „To rzecz nieklawa, Nie mój dach i nie moja sprawa…" Wezwali wójta sąsiedzi, A Ciaptak na dachu siedzi, Syczy, burczy i prycha. A cóż to za stwór, do licha? Wójt do urzędu wszedł i Zagłębił się encyklopedii. „Ce… Ciaptak… Nie ma Ciaptaka… A może to rodzaj buraka, Ogórka albo ziemniaka?" A Ciaptak na dachu siedzi, Natrząsa się gawiedzi. Tłum rośnie, gapią się gapie, No, kto go za ogon złapie? „Też mądry! Ciaptak nie wrona, On wcale nie ma ogona!" „Co ty tam wiesz, patałachu?!" A Ciaptak siedzi na dachu, Nabzdyczył się i nadął. Aż nagle zleciał na dół. Ludzie za nim pognali w te pędy, A on kluczył tędy, owędy, Przez pole, przez rzeczkę, przez las, Tam szybko na drzewo wlazł I wskoczył do dziupli w drzewie. A co to jest Ciaptak - nikt nie wie.', 'Ciaptak');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (9, 'MEDIUM', 'Stoi na stacji lokomotywa, Ciężka, ogromna i pot z niej spływa: Tłusta oliwa. Stoi i sapie, dyszy i dmucha, Żar z rozgrzanego jej brzucha bucha: Uch - jak gorąco! Puff - jak gorąco! Uff - jak gorąco! Już ledwo sapie, już ledwo zipie, A jeszcze palacz węgiel w nią sypie. Wagony do niej podoczepiali Wielkie i ciężkie, z żelaza, stali, I pełno ludzi w każdym wagonie, A w jednym krowy, a w drugim konie, A w trzecim siedzą same grubasy, Siedzą i jedzą tłuste kiełbasy, A czwarty wagon pełen bananów, A w piątym stoi sześć fortepianów, W szóstym armata - o! jaka wielka! Pod każdym kołem żelazna belka! W siódmym dębowe stoły i szafy, W ósmym słoń, niedźwiedź i dwie żyrafy, W dziewiątym - same tuczone świnie, W dziesiątym - kufry, paki i skrzynie, A tych wagonów jest ze czterdzieści, Sam nie wiem, co się w nich jeszcze mieści.', 'Lokomotywa');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (10, 'MEDIUM', 'Na tapczanie siedzi leń, Nic nie robi cały dzień. „O, wypraszam to sobie! Jak to? Ja nic nie robię? A kto siedzi na tapczanie? A kto zjadł pierwsze śniadanie? A kto dzisiaj pluł i łapał? A kto się w głowę podrapał? A kto dziś zgubił kalosze? O - o! Proszę!" Na tapczanie siedzi leń, Nic nie robi cały dzień.', 'Leń');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (11, 'MEDIUM', 'Dawno temu, choć nikt o tym nie wie, Marchewka rosła na drzewie, A że tak wysoko rosła - Była okropnie wyniosła. O kapuście mówiła „kapucha", Z brukwi się wyśmiewała, że jest tłustobrzucha, A jak się wyrażała o rzepie, Nawet nie wspominać lepiej.', 'Marchewka');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (12, 'MEDIUM', 'Biega, krzyczy pan Hilary: "Gdzie są moje okulary?" Szuka w spodniach i w surducie, W prawym bucie, w lewym bucie. Wszystko w szafach poprzewracał, Maca szlafrok, palto maca. "Skandal! – krzyczy - nie do wiary! Ktoś mi ukradł okulary!" Pod kanapą, na kanapie, Wszędzie szuka, parska, sapie! Szpera w piecu i w kominie, W mysiej dziurze i w pianinie. Już podłogę chce odrywać, Już policję zaczął wzywać. Nagle - zerknął do lusterka… Nie chce wierzyć… Znowu zerka. Znalazł! Są! Okazało się, Że je ma na własnym nosie.', 'Okulary');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (13, 'ADVANCED', 'Idź dokąd poszli tamci do ciemnego kresu po złote runo nicości twoją ostatnią nagrodę idź wyprostowany wśród tych co na kolanach wśród odwróconych plecami i obalonych w proch ocalałeś nie po to aby żyć masz mało czasu trzeba dać świadectwo bądź odważny gdy rozum zawodzi bądź odważny w ostatecznym rachunku jedynie to się liczy', 'Przesłanie Pana Cogito');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (14, 'ADVANCED', 'Oczywiście ci którzy stoją na szczycie schodów oni wiedzą oni wiedzą wszystko co innego my sprzątacze placów zakładnicy lepszej przyszłości którym ci ze szczytu schodów ukazują się rzadko zawsze z palcem na ustach jesteśmy cierpliwi żony nasze cerują niedzielną koszulę rozmawiamy o racjach żywności o piłce nożnej cenie butów', 'Ze schodu szczytów');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (15, 'ADVANCED', 'Litwo! Ojczyzno moja! ty jesteś jak zdrowie. Ile cię trzeba cenić, ten tylko się dowie, Kto cię stracił. Dziś piękność twą w całej ozdobie Widzę i opisuję, bo tęsknię po tobie.', 'Pan Tadeusz - Inwokacja');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (16, 'ADVANCED', 'Oto dziś dzień krwi i chwały, Oby dniem wskrzeszenia był! W tęczę Franków Orzeł Biały Patrząc, lot swój w niebo wzbił.', 'Warszawianka');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (17, 'ADVANCED', 'Hrabia Roland usłyszał swoje nazwisko. Zaczem rzekł, Jak powinien uczynić rycerz: „Panie ojczymie, winienem cię miłować, wybrałeś mnie na tylną straż.', 'Pieśń o Rolandzie-fragmenty');
INSERT INTO writing_texts (id_writing_text, level, text, title) VALUES
    (18, 'ADVANCED', 'Psychic spies from China Try to steal your minds elation Little girls from Sweden Dream of silver screen quotations And if you want these kind of dreams Its Californication', 'Californication');
